def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C'

    opp_last = history[-1][1]
    my_last = history[-1][0]

    opp_def = 0
    my_def = 0
    for m, o in history:
        if o == 'D':
            opp_def += 1
        if m == 'D':
            my_def += 1

    recent = history[-10:]
    opp_def_10 = sum(1 for _, o in recent if o == 'D')

    # Endgame
    if n >= 90:
        if opp_def == 0:
            return 'D'
        if my_def < 5 and opp_def_10 == 0:
            return 'D'
        return 'C'

    # If opponent has never defected, test defection.
    if opp_def == 0:
        if my_def >= 3 and n >= 15:
            return 'D'
        if my_last == 'C' and rng.random() < 0.3:
            return 'D'
        return 'C'

    # If opponent defected last round, appease unless they are defecting a lot.
    if opp_last == 'D':
        if opp_def_10 >= 4:
            return 'D'
        return 'C'

    # Opponent cooperated last round.
    rate = opp_def / n
    if rate < 0.1:
        if my_last == 'D':
            return 'C'
        if rng.random() < 0.15:
            return 'D'
        return 'C'
    if rate < 0.2:
        if my_last == 'D':
            return 'C'
        if rng.random() < 0.08:
            return 'D'
        return 'C'
    if rate < 0.3:
        if my_last == 'D':
            return 'C'
        if rng.random() < 0.03:
            return 'D'
        return 'C'

    return 'C'
